package com.hablapatabla.implingfinder.model;
import lombok.AllArgsConstructor;
import lombok.Getter;
import java.util.HashMap;
import java.util.Map;
@Getter
@AllArgsConstructor
public enum ImplingFinderEnum {
    BABY(1635, "Baby impling"),
    YOUNG(1636, "Young impling"),
    GOURMET(1637, "Gourmet impling"),
    EARTH(1638, "Earth impling"),
    ESSENCE(1639, "Essence impling"),
    ECLECTIC(1640, "Eclectic impling"),
    NATURE(1641, "Nature impling"),
    MAGPIE(1642, "Magpie impling"),
    NINJA(1643, "Ninja impling"),
    DRAGON(1644, "Dragon impling"),
    LUCKY(7233, "Lucky impling"),
    CRYSTAL(8741, "Crystal impling"),
    RECENT(-1, "Recent");
    private int npcId;
    private String name;

    // Notable drop info per type, single source of truth used by both the
    // filter button tooltips and the Drops reference panel. Clue tiers and
    // rates verified against the OSRS Wiki. Where the wiki confirms a clue
    // tier exists but doesn't give a clean numeric rate (Baby, Young, Earth,
    // Dragon), that's stated plainly rather than a guessed number.
    public static final Map<String, String> DROP_INFO = new HashMap<String, String>() {{
        put("Baby",     "Clue: Beginner (rate not listed by Jagex)");
        put("Young",    "Clue: Beginner (better odds than Baby)");
        put("Gourmet",  "Clue: Easy (1/25)");
        put("Earth",    "Clue: Medium (rate not listed by Jagex)");
        put("Essence",  "Clue: Medium (1/50)");
        put("Eclectic", "Clue: Medium (1/25) - best medium clue farming method (Ranger boots)");
        put("Nature",   "Clue: Hard (1/100)");
        put("Magpie",   "Clue: Hard (1/50)");
        put("Ninja",    "Clue: Hard (1/25)");
        put("Crystal",  "No clue scrolls. Crystal shards + crystal acorns, not GE-tradeable");
        put("Dragon",   "Clue: Elite (only impling source of elite clues)");
        put("Lucky",    "Equal-odds roll into easy/medium/hard/elite/master tables (no master clue or bloodhound possible)");
    }};

    private static final Map<Integer, ImplingFinderEnum> map;
    static {
        map = new HashMap<>();
        for (ImplingFinderEnum e : ImplingFinderEnum.values())  {
            map.put(e.npcId, e);
        }
        // Jar variant NPC IDs map to the same impling type
        map.put(1645, BABY);
        map.put(1646, YOUNG);
        map.put(1647, GOURMET);
        map.put(1648, EARTH);
        map.put(1649, ESSENCE);
        map.put(1650, ECLECTIC);
        map.put(1651, NATURE);
        map.put(1652, MAGPIE);
        map.put(1653, NINJA);
        map.put(1654, DRAGON);
        map.put(7302, LUCKY);
        map.put(8742, CRYSTAL);
        map.put(8743, CRYSTAL);
        map.put(8744, CRYSTAL);
        map.put(8745, CRYSTAL);
        map.put(8746, CRYSTAL);
        map.put(8747, CRYSTAL);
        map.put(8748, CRYSTAL);
        map.put(8749, CRYSTAL);
        map.put(8750, CRYSTAL);
        map.put(8751, CRYSTAL);
        map.put(8752, CRYSTAL);
        map.put(8753, CRYSTAL);
        map.put(8754, CRYSTAL);
        map.put(8755, CRYSTAL);
        map.put(8756, CRYSTAL);
        map.put(8757, CRYSTAL);
    }
    public static ImplingFinderEnum findById(int id) {
        return map.get(id);
    }
    public static int getIdByNameFuzzy(String name) {
        for (ImplingFinderEnum imp : values()) {
            if (imp.name.contains(name))
                return imp.npcId;
        }
        return -1;
    }
    public static int getIdByNameStrict(String name) {
        for (ImplingFinderEnum imp : values()) {
            if (name.contains(imp.name))
                return imp.npcId;
        }
        return -1;
    }
}

package com.hablapatabla.implingfinder.model;

import com.google.gson.annotations.SerializedName;
import lombok.Builder;
import lombok.Getter;
import lombok.Value;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.Instant;

@Value
@Builder
public class ImplingFinderData implements Comparable {
    @Getter
    @SerializedName("npcid")
    private int npcid;

    @Getter
    @SerializedName("world")
    private int world;

    @Getter
    @SerializedName("xcoord")
    private int xcoord;

    @Getter
    @SerializedName("ycoord")
    private int ycoord;

    @Getter
    @SerializedName("plane")
    private int plane;

    @Getter
    @SerializedName("discoveredtime")
    private Instant discoveredtime;

    private static Logger logger = LoggerFactory.getLogger(ImplingFinderData.class);

    @Override
    public String toString() {
        return "" + npcid + "  " + world + "  " + xcoord + "  " + ycoord + "  " + plane + "  " + discoveredtime.toString();
    }

    @Override
    public int compareTo(Object o) {
        ImplingFinderData other = (ImplingFinderData) o;
        return this.discoveredtime.compareTo(other.getDiscoveredtime());
    }
}

package com.hablapatabla.implingfinder.model;

import com.hablapatabla.implingfinder.ImplingFinderPlugin;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;

import java.awt.*;
import java.awt.image.BufferedImage;

public class ImplingFinderWorldMapPoint extends WorldMapPoint
{
    private final ImplingFinderPlugin plugin;
    private final BufferedImage worldImage;
    private final Point worldImagePoint;

    public ImplingFinderWorldMapPoint(final WorldPoint worldPoint, ImplingFinderPlugin plugin)
    {
        super(worldPoint, null);

        worldImage = new BufferedImage(plugin.getWorldMapImage().getWidth(), plugin.getWorldMapImage().getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics graphics = worldImage.getGraphics();
        graphics.drawImage(plugin.getWorldMapImage(), 0, 0, null);
        graphics.drawImage(plugin.getWorldMapImage(), 0, 0, null);
        worldImagePoint = new Point(
                worldImage.getWidth(),
                worldImage.getHeight());

        this.plugin = plugin;
        this.setName("Impling");
        this.setSnapToEdge(true);
        this.setJumpOnClick(true);
        this.setImage(worldImage);
        this.setImagePoint(worldImagePoint);
    }

    @Override
    public void onEdgeSnap() {
        this.setImage(plugin.getWorldMapImage());
        this.setImagePoint(null);
    }

    @Override
    public void onEdgeUnsnap() {
        this.setImage(worldImage);
        this.setImagePoint(worldImagePoint);
    }
}

package com.hablapatabla.implingfinder.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.shadowlabel.JShadowedLabel;

/**
 * A component to display an error/info message (to be used on a plugin panel)
 * Example uses are: no ge search results found, no ge offers found.
 */
public class ImplingFinderSplashPanel extends JPanel
{
    private final JLabel noResultsTitle = new JShadowedLabel();
    private final JLabel noResultsDescription = new JShadowedLabel();

    public ImplingFinderSplashPanel()
    {
        setOpaque(false);
        setBorder(new EmptyBorder(50, 10, 0, 10));
        setLayout(new BorderLayout());

        noResultsTitle.setForeground(Color.WHITE);
        noResultsTitle.setHorizontalAlignment(SwingConstants.CENTER);

        noResultsDescription.setFont(FontManager.getRunescapeFont());
        noResultsDescription.setForeground(Color.GRAY);
        noResultsDescription.setHorizontalAlignment(SwingConstants.CENTER);

        add(noResultsTitle, BorderLayout.NORTH);
        add(noResultsDescription, BorderLayout.CENTER);

        setVisible(false);
    }

    /**
     * Changes the content of the panel to the given parameters.
     * The description has to be wrapped in html so that its text can be wrapped.
     */
    public void setContent(String title, String description)
    {
        noResultsTitle.setText(title);
        noResultsDescription.setText("<html><body style = 'text-align:center'>" + description + "</body></html>");
        setVisible(true);
    }
}

package com.hablapatabla.implingfinder.ui;

import com.hablapatabla.implingfinder.model.ImplingFinderData;
import com.hablapatabla.implingfinder.model.ImplingFinderEnum;
import com.hablapatabla.implingfinder.ImplingFinderPlugin;
import com.hablapatabla.implingfinder.model.ImplingFinderRegion;
import net.runelite.api.ItemID;
import net.runelite.api.NpcID;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class ImplingFinderImpPanel extends JPanel {
    private static final Dimension ICON_SIZE = new Dimension(32, 32);

    // Tracks which panel was last clicked so it can be visually highlighted
    // and so a second click on the same panel can toggle the highlight off,
    // matching the existing toggle behaviour of the map marker itself.
    private static ImplingFinderImpPanel selectedPanel = null;

    @Inject
    private WorldMapPointManager worldMapPointManager;

    // npc id to ItemID
    // Expanded from 5 entries (Magpie, Ninja, Crystal, Dragon, Lucky) to all 13
    // impling types now that ImplingFinderEnum tracks every type.
    private static Map<Integer, Integer> thumbnails = new HashMap<Integer, Integer>() {{
        put(NpcID.BABY_IMPLING, ItemID.BABY_IMPLING_JAR);
        put(NpcID.YOUNG_IMPLING, ItemID.YOUNG_IMPLING_JAR);
        put(NpcID.GOURMET_IMPLING, ItemID.GOURMET_IMPLING_JAR);
        put(NpcID.EARTH_IMPLING, ItemID.EARTH_IMPLING_JAR);
        put(NpcID.ESSENCE_IMPLING, ItemID.ESSENCE_IMPLING_JAR);
        put(NpcID.ECLECTIC_IMPLING, ItemID.ECLECTIC_IMPLING_JAR);
        put(NpcID.NATURE_IMPLING, ItemID.NATURE_IMPLING_JAR);
        put(NpcID.MAGPIE_IMPLING, ItemID.MAGPIE_IMPLING_JAR);
        put(NpcID.NINJA_IMPLING, ItemID.NINJA_IMPLING_JAR);
        put(NpcID.CRYSTAL_IMPLING, ItemID.CRYSTAL_IMPLING_JAR);
        put(NpcID.DRAGON_IMPLING, ItemID.DRAGON_IMPLING_JAR);
        put(NpcID.LUCKY_IMPLING, ItemID.LUCKY_IMPLING_JAR);
    }};

    private static final String[] COMPASS_DIRECTIONS = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

    private Logger logger = LoggerFactory.getLogger(ImplingFinderImpPanel.class);
    private List<JPanel> panels = new ArrayList<>();

    protected ImplingFinderPlugin plugin;

    public static int getItemIdFromNpcId(int id) {
        Integer itemId = thumbnails.get(id);
        // Fallback to a generic jar icon if a type is somehow missing
        // from the map, instead of throwing a NullPointerException.
        return itemId != null ? itemId : ItemID.BABY_IMPLING_JAR;
    }

    /**
     * Computes the compass direction (N, NE, E, SE, S, SW, W, NW) from one
     * point to another using standard bearing math: angle = atan2(dx, dy),
     * measured clockwise from north, then snapped to the nearest of 8
     * compass points.
     */
    private static String compassDirection(WorldPoint from, WorldPoint to) {
        int dx = to.getX() - from.getX();
        int dy = to.getY() - from.getY();
        double angle = Math.toDegrees(Math.atan2(dx, dy));
        if (angle < 0)
            angle += 360;
        int index = (int) Math.round(angle / 45.0) % 8;
        return COMPASS_DIRECTIONS[index];
    }

    ImplingFinderImpPanel(ItemManager manager, ImplingFinderData data, Integer defaultId, ImplingFinderPlugin plugin, WorldPoint playerLocation) {
        this.plugin = plugin;
        Color background = getBackground();
        BorderLayout layout = new BorderLayout();
        layout.setHgap(5);
        setLayout(layout);
        setToolTipText(ImplingFinderEnum.findById(data.getNpcid()).getName());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        panels.add(this);
        setBorder(new EmptyBorder(7, 0, 0, 0));


        WorldPoint implingWorldPoint = new WorldPoint(data.getXcoord(), data.getYcoord(), data.getPlane());

        MouseAdapter itemPanelMouseListener = new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) {
                if (selectedPanel == ImplingFinderImpPanel.this)
                    return;
                for (JPanel p : panels)
                    matchComponentBackground(p, ColorScheme.DARK_GRAY_HOVER_COLOR);
                setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                if (selectedPanel == ImplingFinderImpPanel.this)
                    return;
                for (JPanel p : panels)
                    matchComponentBackground(p, ColorScheme.DARKER_GRAY_COLOR);
                setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                plugin.addMapPoints(implingWorldPoint);

                // Toggle highlight: clicking the already-selected panel clears
                // the highlight (matches the map marker's own toggle behaviour),
                // clicking a different panel moves the highlight to it.
                ImplingFinderImpPanel previouslySelected = selectedPanel;
                if (previouslySelected != null) {
                    for (JPanel p : previouslySelected.panels)
                        previouslySelected.matchComponentBackground(p, ColorScheme.DARKER_GRAY_COLOR);
                }

                if (previouslySelected == ImplingFinderImpPanel.this) {
                    selectedPanel = null;
                } else {
                    selectedPanel = ImplingFinderImpPanel.this;
                    for (JPanel p : panels)
                        matchComponentBackground(p, ColorScheme.DARK_GRAY_HOVER_COLOR.brighter());
                }
            }
        };

        addMouseListener(itemPanelMouseListener);

        final JLabel itemIcon = new JLabel();
        itemIcon.setPreferredSize(ICON_SIZE);
        Integer id = thumbnails.get(data.getNpcid());
        AsyncBufferedImage icon;
        if (id != null)
            manager.getImage(id).addTo(itemIcon);
        else
            manager.getImage(defaultId).addTo(itemIcon);

        JPanel iconPanel = new JPanel();
        panels.add(iconPanel);
        iconPanel.add(itemIcon);
        add(iconPanel, BorderLayout.LINE_START);


        JPanel rightPanel = new JPanel(new GridLayout(4, 1));
        panels.add(rightPanel);
        rightPanel.setBackground(background);

        JLabel itemName = new JLabel();
        itemName.setForeground(Color.WHITE);
        itemName.setMaximumSize(new Dimension(0, 0));        // to limit the label's size for
        itemName.setPreferredSize(new Dimension(0, 0));    // items with longer names
        itemName.setText(ImplingFinderEnum.findById(data.getNpcid()).getName());
        rightPanel.add(itemName);

        JPanel middleTextPanel = new JPanel(new BorderLayout());
        middleTextPanel.setBackground(background);
        panels.add(middleTextPanel);

        JLabel middleLeftTextLabel = new JLabel();
        middleLeftTextLabel.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);

        middleLeftTextLabel.setText("World: " + data.getWorld());
        middleTextPanel.add(middleLeftTextLabel, BorderLayout.WEST);

        JLabel middleRightTextLabel = new JLabel();
        middleRightTextLabel.setForeground(ColorScheme.GRAND_EXCHANGE_ALCH);
        String day;
        long daysBetween = ChronoUnit.DAYS.between(data.getDiscoveredtime(), Instant.now());
        if (daysBetween == 0)
            day = "Today";
        else if (daysBetween == 1)
            day = "Yesterday";
        else
            day = daysBetween + " days ago";

        middleRightTextLabel.setText(day);
        middleTextPanel.add(middleRightTextLabel, BorderLayout.EAST);
        rightPanel.add(middleTextPanel);

        // New row: shows compass direction + tile distance from the player's
        // current location to this impling, e.g. "NE, 340 tiles". Only shown
        // when the player's location and the impling are on the same plane,
        // since cross-plane distance/direction isn't meaningful.
        JPanel directionRowPanel = new JPanel(new BorderLayout());
        directionRowPanel.setBackground(background);
        panels.add(directionRowPanel);

        JLabel directionLabel = new JLabel();
        directionLabel.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);
        if (playerLocation != null && playerLocation.getPlane() == implingWorldPoint.getPlane()) {
            String direction = compassDirection(playerLocation, implingWorldPoint);
            int distance = (int) Math.round(Math.sqrt(
                    Math.pow(implingWorldPoint.getX() - playerLocation.getX(), 2) +
                    Math.pow(implingWorldPoint.getY() - playerLocation.getY(), 2)));
            directionLabel.setText(direction + ", " + distance + " tiles");
        } else {
            directionLabel.setText("Different area");
        }
        directionRowPanel.add(directionLabel, BorderLayout.WEST);
        rightPanel.add(directionRowPanel);

        JPanel bottomTextRowPanel = new JPanel(new BorderLayout());
        bottomTextRowPanel.setBackground(background);
        panels.add(bottomTextRowPanel);

        JLabel bottomLeftTextLabel = new JLabel();
        String foundTime = data.getDiscoveredtime().atZone(ZoneId.systemDefault())
                        .format(DateTimeFormatter.ofLocalizedTime(FormatStyle.LONG));
        bottomLeftTextLabel.setText(foundTime);
        bottomLeftTextLabel.setForeground(ColorScheme.GRAND_EXCHANGE_ALCH);
        bottomTextRowPanel.add(bottomLeftTextLabel, BorderLayout.WEST);

        final int playerRegionId = implingWorldPoint.getRegionID();
        String location;
        if (ImplingFinderRegion.fromRegion(playerRegionId) != null)
            location = ImplingFinderRegion.fromRegion(playerRegionId).getName();
        else
            location = "Unknown";
        location = StringUtils.abbreviate(location, 12);

        JLabel bottomRightTextLabel = new JLabel();
        bottomRightTextLabel.setText(location);
        bottomRightTextLabel.setForeground(ColorScheme.GRAND_EXCHANGE_LIMIT);
        bottomRightTextLabel.setBorder(new CompoundBorder(bottomRightTextLabel.getBorder(), new EmptyBorder(0, 0, 0, 7)));
        bottomTextRowPanel.add(bottomRightTextLabel, BorderLayout.EAST);

        rightPanel.add(bottomTextRowPanel);

        for (JPanel p : panels)
            matchComponentBackground(p, ColorScheme.DARKER_GRAY_COLOR);

        add(rightPanel, BorderLayout.CENTER);
    }

    private void matchComponentBackground(JPanel panel, Color color) {
        panel.setBackground(color);
        for (Component c : panel.getComponents()) {
            c.setBackground(color);
        }
    }
}

package com.hablapatabla.implingfinder.ui;

import com.hablapatabla.implingfinder.model.ImplingFinderEnum;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * Static reference panel listing notable drops (clue tiers, rates, unique
 * loot) for every impling type. Built once from ImplingFinderEnum.DROP_INFO -
 * the same data source the filter button tooltips use - so this and the
 * tooltips can never drift out of sync with each other.
 */
class ImplingFinderDropsPanel extends JPanel {

    // Kept in a sensible order (weakest to strongest) rather than whatever
    // order the underlying HashMap happens to iterate in.
    private static final String[] ORDER = {
        "Baby", "Young", "Gourmet", "Earth", "Essence", "Eclectic",
        "Nature", "Magpie", "Ninja", "Crystal", "Dragon", "Lucky"
    };

    ImplingFinderDropsPanel() {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        listPanel.setBorder(new EmptyBorder(8, 10, 8, 10));

        JLabel heading = new JLabel("Notable Drops by Type");
        heading.setForeground(Color.WHITE);
        heading.setFont(heading.getFont().deriveFont(Font.BOLD, 14f));
        heading.setAlignmentX(Component.LEFT_ALIGNMENT);
        heading.setBorder(new EmptyBorder(0, 0, 8, 0));
        listPanel.add(heading);

        for (String type : ORDER) {
            String info = ImplingFinderEnum.DROP_INFO.get(type);
            if (info == null) continue;

            JPanel row = new JPanel(new BorderLayout());
            row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            row.setBorder(new EmptyBorder(6, 8, 6, 8));
            row.setAlignmentX(Component.LEFT_ALIGNMENT);
            row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 60));

            JLabel typeLabel = new JLabel(type);
            typeLabel.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);
            typeLabel.setFont(typeLabel.getFont().deriveFont(Font.BOLD));

            JLabel infoLabel = new JLabel("<html><body style='width: 180px'>" + info + "</body></html>");
            infoLabel.setForeground(Color.LIGHT_GRAY);

            row.add(typeLabel, BorderLayout.NORTH);
            row.add(infoLabel, BorderLayout.CENTER);

            listPanel.add(row);
            listPanel.add(Box.createRigidArea(new Dimension(0, 4)));
        }

        JLabel footnote = new JLabel(
            "<html><body style='width: 180px'>Rates verified against the OSRS Wiki. " +
            "Where no exact rate is listed, that's stated rather than guessed.</body></html>");
        footnote.setForeground(Color.GRAY);
        footnote.setBorder(new EmptyBorder(10, 0, 0, 0));
        footnote.setAlignmentX(Component.LEFT_ALIGNMENT);
        listPanel.add(footnote);

        JScrollPane scrollPane = new JScrollPane(listPanel);
        scrollPane.setBorder(null);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);

        add(scrollPane, BorderLayout.CENTER);
    }
}

