    private Client client;

    @Inject
    protected ImplingFinderPanel(ImplingFinderPlugin plugin, ItemManager itemManager) {
        this.plugin = plugin;
        this.itemManager = itemManager;
        implingFinderPanelHelper(plugin);
    }

    private void implingFinderPanelHelper(ImplingFinderPlugin plugin) {
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        c.fill = GridBagConstraints.HORIZONTAL;
        c.weightx = 1;
        c.gridx = 0;
        c.anchor = GridBagConstraints.PAGE_START;

        /*
         * Mockup of overall Panel
         *
         * {
         *     [(clear)        (Impling Finder)]  - clearButton, title
         *  {
         *     [(Recent) (Baby) (Young)
         *      (Gourmet) (Earth) (Essence)
         *      (Eclectic) (Nature) (Magpie)
         *      (Ninja) (Dragon) (Lucky)
         *      (Crystal)                  ]  - implingSelections (4x4 GridLayout, 13 used)
         *     [           (Fetch)            ]  - fetchButton
         *  } - fetchPanel
         * } - topContainer
         *
         * {
         *        [ IMPLING LIST ]
         * } - container
         *
         */

        /*
         * Subpanel for all buttons and info at top of the overall Impling Finder panel
         */
        JPanel topContainer = new JPanel();
        topContainer.setLayout(new BorderLayout());
        topContainer.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0,
                                                            ColorScheme.DARKER_GRAY_HOVER_COLOR));

        /*
         * Subpanel for title and clear button in top row of topContainer panel
         */
        JPanel titlePanel = new JPanel();
        titlePanel.setBorder(new EmptyBorder(10, 0, 10, 0));
        titlePanel.setLayout(new BorderLayout());

        JLabel title = new JLabel();
        title.setText("Impling Finder");
        title.setForeground(Color.WHITE);
        titlePanel.add(title, BorderLayout.EAST);

        JButton clearButton = new JButton("Clear");
        clearButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                clearRequested = true;
            }
        });
        clearButton.setForeground(Color.WHITE);
        clearButton.setRequestFocusEnabled(false);

        // Toggle between the normal impling list and the static Drops
        // reference panel. Doesn't need any "back" logic of its own -
        // clicking Fetch or Clear afterward naturally switches the view
        // back via the existing cardLayout.show() calls elsewhere.
        JButton dropsButton = new JButton("Drops");
        dropsButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                cardLayout.show(implingListContainer, DROPS_PANEL);
            }
        });
        dropsButton.setForeground(Color.WHITE);
        dropsButton.setRequestFocusEnabled(false);

        JPanel leftButtonsPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        leftButtonsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        leftButtonsPanel.add(clearButton);
        leftButtonsPanel.add(dropsButton);
        titlePanel.add(leftButtonsPanel, BorderLayout.WEST);

        topContainer.add(titlePanel, BorderLayout.NORTH);

        /*
         * Lower fetch panel, contains impling buttons and fetch button
         */

        JPanel fetchPanel = new JPanel();
        fetchPanel.setLayout(new BorderLayout());
        fetchPanel.setBorder(new EmptyBorder(0, 0, 5, 0));

        // Grid expanded from 2x3 (6 buttons) to 4x4 (fits all 13 + 3 spare slots)
        JPanel implingSelections = new JPanel(new GridLayout(4, 4));
        implingSelections.setBorder(new EmptyBorder(0, -1, 3, -1));
        populateButtonList();
        for (JButton p : buttonList)
            implingSelections.add(p);
        fetchPanel.add(implingSelections, BorderLayout.NORTH);

        JLabel donateLabel = new JLabel("Enjoying the plugin? Consider supporting it \u2764");
        donateLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        donateLabel.setFont(donateLabel.getFont().deriveFont(11f));
        donateLabel.setHorizontalAlignment(SwingConstants.CENTER);
        donateLabel.setBorder(new EmptyBorder(4, 0, 4, 0));
        donateLabel.setCursor(new Cursor(Cursor.HAND_CURSOR));
        donateLabel.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                LinkBrowser.browse("https://ko-fi.com/koopyosrs");
            }
        });

        JButton fetchButton = new JButton("Fetch");
        fetchButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                fetchRequested = true;
            }
        });
        fetchButton.setForeground(Color.WHITE);
        fetchButton.setRequestFocusEnabled(false);

        JPanel fetchBottomPanel = new JPanel();
        fetchBottomPanel.setLayout(new BoxLayout(fetchBottomPanel, BoxLayout.Y_AXIS));
        fetchBottomPanel.add(donateLabel);
        fetchBottomPanel.add(fetchButton);
        fetchPanel.add(fetchBottomPanel, BorderLayout.SOUTH);

        topContainer.add(fetchPanel, BorderLayout.SOUTH);

        this.add(topContainer, BorderLayout.NORTH);

        /*
         * End topContainer, add impling list
         */

        impListPanel.setLayout(new GridBagLayout());
        impListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel impsWrapper = new JPanel(new BorderLayout());
        impsWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        impsWrapper.add(impListPanel, BorderLayout.NORTH);

        JPanel errorWrapper = new JPanel(new BorderLayout());
        errorWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        errorPanel.setContent("Nothing to display    :(",
                "Either I have no implings to show you, or an error has occurred.");
        errorWrapper.add(errorPanel, BorderLayout.NORTH);


        JPanel splashWrapper = new JPanel(new BorderLayout());
        splashWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
        splashPanel.setContent("Welcome to Impling Finder!",
                " This plugin watches for implings around you, and uploads their locations to a shared" +
                        " server so everyone using the plugin can find them faster. Try clicking a found impling" +
                        " to see its exact location on your worldmap. Check 'Splash Seen' in the config so you" +
                        " don't see this page again. Uploads are only done when implings are actually found, so" +
                        " this plugin uses virtually no network bandwidth. Found a bug or have a feature idea?" +
                        " Raise it on the GitHub repo. Want to hang out, get updates, or report something" +
                        " directly? Join the Discord: https://discord.gg/4cuFQGvDk2. This plugin crowdsources" +
                        " data, so the more people using it, the better it works for everyone. Tell your" +
                        " friends to install!");
        splashWrapper.add(splashPanel, BorderLayout.NORTH);

        JButton getStartedButton = new JButton("Let's get started");
        getStartedButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                continuePastSplash();
            }
        });
        splashWrapper.add(getStartedButton, BorderLayout.SOUTH);

        implingListContainer.add(splashWrapper, SPLASH_PANEL);
        implingListContainer.add(impsWrapper, RESULTS_PANEL);
        implingListContainer.add(errorWrapper, ERROR_PANEL);
        implingListContainer.add(new ImplingFinderDropsPanel(), DROPS_PANEL);

        cardLayout.show(implingListContainer, SPLASH_PANEL);

        this.add(implingListContainer, BorderLayout.CENTER);
    }

    public void notifyButtonSelected(String s) {
        for (ImplingFinderButton ib : buttonList) {
            if ((s.equals("Recent") && !ib.getName().equals("Recent")) ||
                    (!s.equals("Recent") && ib.getName().equals("Recent")))
                ib.setSelected(false);
            ib.paint(ib.getGraphics());
        }
    }

    public List<Integer> getSelectedButtons() {
        List<Integer> l = new ArrayList<>();
        for (ImplingFinderButton ib : buttonList) {
            if (ib.isSelected())
                l.add(ImplingFinderEnum.getIdByNameFuzzy(ib.getName()));
        }
        return l;
    }

    private void populateButtonList() {
        buttonList.clear();
        for (String s : TargetableImplings) {
            Image i;
            int id = ImplingFinderEnum.getIdByNameFuzzy(s);
            if (id == ImplingFinderPlugin.RECENT_IMPLINGS_ID)
                i = itemManager.getImage(ItemID.TEAK_CLOCK);
            else {
                int itemid = ImplingFinderImpPanel.getItemIdFromNpcId(id);
                i = itemManager.getImage(itemid);
            }
            ImplingFinderButton b = new ImplingFinderButton(i, s);

            b.addActionListener(new ActionListener() {
                @Override
                public void actionPerformed(ActionEvent e) {
                    b.setSelected(!b.isSelected());
                    notifyButtonSelected(b.getName());
                }
            });

            // Always start with Recent selected
            if (id == ImplingFinderPlugin.RECENT_IMPLINGS_ID)
                b.setSelected(true);
            buttonList.add(b);
        }
    }

    public void showSplash() {
        cardLayout.show(implingListContainer, SPLASH_PANEL);
    }

    public void continuePastSplash() {
        cardLayout.show(implingListContainer, ERROR_PANEL);
    }

    /**
     * @param npcs list of implings to display
     * @param playerLocation the player's current location, captured safely
     *                       on the client thread by the caller, or null if
     *                       unavailable (e.g. not logged in). Used to show
     *                       compass direction/distance to each impling.
     */
    public void populateNpcs(List<ImplingFinderData> npcs, WorldPoint playerLocation) {
        c.gridy = 0;
        c.weighty = 0;

        impListPanel.removeAll();

        if (npcs.size() == 0) {
            cardLayout.show(implingListContainer, ERROR_PANEL);
            return;
        }
        cardLayout.show(implingListContainer, RESULTS_PANEL);

        List<JPanel> implings = new ArrayList<>();
        int defaultThumbnailId = ItemID.BABY_MOLERAT;
        for (ImplingFinderData npc : npcs) {
            JPanel marginWrapper = new JPanel(new BorderLayout());
            marginWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
            // Magic numbers yikes
            marginWrapper.setBorder(new EmptyBorder(5, 0 ,0 ,-4));

            ImplingFinderImpPanel imp = new ImplingFinderImpPanel(itemManager, npc, defaultThumbnailId, plugin, playerLocation);
            imp.setAutoscrolls(true);
            imp.setBorder(new EmptyBorder(3, 0 ,0 ,7));
            marginWrapper.add(imp);

            implings.add(marginWrapper);
        }

        for (JPanel p : implings) {
            impListPanel.add(p, c);
            c.gridy += 1;
        }

        repaint();
        revalidate();
    }
}

package com.hablapatabla.implingfinder.ui;
import com.hablapatabla.implingfinder.model.ImplingFinderEnum;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.ColorScheme;
import javax.swing.*;
import javax.swing.border.EtchedBorder;
import java.awt.*;
@SuppressWarnings("serial")
class ImplingFinderButton extends JButton {
    @Getter
    @Setter
    private boolean selected;
    @Getter
    @Setter
    private String name;

    ImplingFinderButton(Image i, String name) {
        super.setContentAreaFilled(false);
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setFocusPainted(false);
        this.setRequestFocusEnabled(false);
        this.selected = false;
        this.name = name;
        this.setIcon(new ImageIcon(i));
        setBorder(new EtchedBorder());
        // Previously these buttons had no tooltip, so users had to guess
        // which impling type each jar icon represented. Now hovering shows
        // the type name plus its notable drops (see ImplingFinderEnum.DROP_INFO,
        // the single shared source of truth also used by the Drops panel).
        // "Recent" is a special filter rather than an impling type.
        if (name.equals("Recent")) {
            this.setToolTipText("Show all recent implings");
        } else {
            String dropInfo = ImplingFinderEnum.DROP_INFO.get(name);
            this.setToolTipText(dropInfo != null
                ? "<html>" + name + " impling<br>" + dropInfo + "</html>"
                : name + " impling");
        }
    }

    @Override
    public void paint(Graphics g) {
        Color oldFg = getForeground();
        Color newFg = oldFg;
        ButtonModel mod = getModel();
        if (mod.isPressed()) {
            g.setColor(ColorScheme.DARK_GRAY_COLOR);
        } else if (mod.isRollover())
            g.setColor(ColorScheme.DARKER_GRAY_HOVER_COLOR);
        else {
            if (selected)
                g.setColor(ColorScheme.DARKER_GRAY_COLOR);
            else
                g.setColor(ColorScheme.DARK_GRAY_COLOR);
        }
        g.fillRect(0, 0, getWidth(), getHeight());
        setForeground(newFg);
        super.paintComponent(g);
        setForeground(oldFg);
    }
}

package com.hablapatabla.implingfinder;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;
import com.hablapatabla.implingfinder.model.ImplingFinderData;
import com.hablapatabla.implingfinder.model.ImplingFinderEnum;
import okhttp3.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;


@Singleton
public class ImplingFinderWebManager {
    protected static final String CONTENT = "Content-Type";
    protected static final String JSON = "application/json";
    private static final MediaType JSONTYPE = MediaType.parse("application/json; charset=utf-8");

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private ImplingFinderPlugin plugin;

    @Inject
    private ImplingFinderConfig config;

    @Inject
    private GsonBuilder gsonBuilder;

    private Logger logger = LoggerFactory.getLogger(ImplingFinderWebManager.class);


    // The fallback project only ever carries these 5 types - Magpie, Ninja,
    // Dragon, Lucky, Crystal. Same set as before (this used to gate what
    // went to Oracle), kept identical on purpose: it's still the right
    // subset - rare/high-value enough to be worth a backup copy, small
    // enough that a free-tier project stays nowhere near its own limits.
    private static boolean isFallbackCompatible(int npcid) {
        switch (npcid) {
            case 1642: case 1652: // Magpie
            case 1643: case 1653: // Ninja
            case 1644: case 1654: // Dragon
            case 7233: case 7302: // Lucky
                return true;
            default:
                return npcid == 8741 || (npcid >= 8742 && npcid <= 8757); // Crystal + jar-colour variants
        }
    }

    protected void postImplings() {
        try {
            // Copy the list before iterating to avoid ConcurrentModificationException —
            // the client thread may add new implings while the scheduler thread is
            // iterating.
            List<ImplingFinderData> toUpload = new ArrayList<>(plugin.getImplingsToUpload());
            for (ImplingFinderData data : toUpload) {
                String json = getGson().toJson(data);

                // Supabase is the primary write target for everyone, for all 12
                // types. The fallback project is written to unconditionally and in
                // parallel for the 5 compatible types (not only when the primary
                // write fails) - continuous real traffic is what keeps that
                // project's free tier from auto-pausing, and it means the fallback
                // is never stale if it's ever actually needed. The other 7 types
                // still have no fallback destination during a Supabase outage - a
                // known, accepted gap rather than a silent one.
                Request supabaseRequest = new Request.Builder()
                        .url(ImplingFinderPlugin.implingSupabasePostEndpoint)
                        .addHeader(CONTENT, JSON)
                        .addHeader("apikey", ImplingFinderPlugin.SUPABASE_ANON_KEY)
                        .addHeader("Authorization", "Bearer " + ImplingFinderPlugin.SUPABASE_ANON_KEY)
                        .addHeader("Prefer", "return=minimal")
                        .post(RequestBody.create(JSONTYPE, json))
                        .build();

                okHttpClient.newCall(supabaseRequest).enqueue(new Callback() {
                    @Override
                    public void onFailure(Call call, IOException e) {
                        logger.error("Supabase write failed", e);
                    }

                    @Override
                    public void onResponse(Call call, Response response) throws IOException {
                        try {
                            if (!response.isSuccessful()) {
                                logger.error("Supabase write unsuccessful (" + response.code() + ")");
                            }
                        }
                        catch (Exception e) {
                            logger.error("Error handling Supabase write response", e);
                        }
                        finally {
                            response.close();
                        }
                    }
                });

                if (isFallbackCompatible(data.getNpcid())) {
                    writeToFallbackSupabase(json);
                }
            }
        } catch (Exception e) {
            logger.error("Outer catch block POST ", e);
        }
        plugin.getImplingsToUpload().clear();
    }

    /**
     * Unconditional dual-write to the fallback Supabase project, for the 5
     * compatible types only (see isFallbackCompatible). Fires alongside the
     * primary write every time, not just on failure - this is what keeps
     * the fallback project's own free tier from auto-pausing on inactivity,
     * and means it's already warm and current if it's ever actually needed
     * for a read.
     */
    private void writeToFallbackSupabase(String json) {
        Request fallbackRequest = new Request.Builder()
                .url(ImplingFinderPlugin.implingFallbackPostEndpoint)
                .addHeader(CONTENT, JSON)
                .addHeader("apikey", ImplingFinderPlugin.FALLBACK_SUPABASE_ANON_KEY)
                .addHeader("Authorization", "Bearer " + ImplingFinderPlugin.FALLBACK_SUPABASE_ANON_KEY)
                .addHeader("Prefer", "return=minimal")
                .post(RequestBody.create(JSONTYPE, json))
                .build();

        okHttpClient.newCall(fallbackRequest).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                logger.error("Fallback Supabase write failed", e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try {
                    if (!response.isSuccessful())
                        logger.error("Fallback Supabase write unsuccessful (" + response.code() + ")");
                }
                catch (Exception e) {
                    logger.error("Error handling fallback Supabase write response", e);
                }
                finally {
                    response.close();
                }
            }
        });
    }

    protected List<ImplingFinderData> getData(List<Integer> ids) {
        boolean wantsAny = ids.contains(ImplingFinderPlugin.RECENT_IMPLINGS_ID);
        List<ImplingFinderData> implings;

        // Supabase is the primary read source for everyone, for all 12
        // types. The fallback project is only queried if the primary read
        // genuinely fails (network/HTTP error) - an empty result is not a
        // failure, it just means nothing's been found recently, and does
        // not trigger a fallback. The fallback only ever has the 5
        // compatible types anyway, since that's all it's ever written.
        try {
            List<ImplingFinderData> supabaseResults = fetchRecent(ImplingFinderPlugin.implingSupabaseGetEndpoint, ImplingFinderPlugin.SUPABASE_ANON_KEY);
            implings = new ArrayList<>();
            for (ImplingFinderData data : supabaseResults) {
                if (wantsAny || ids.contains(data.getNpcid())) {
                    implings.add(data);
                }
            }
        } catch (Exception e) {
            logger.error("Supabase read failed, falling back to backup Supabase project", e);
            implings = new ArrayList<>();
            try {
                List<ImplingFinderData> fallbackResults = fetchRecent(ImplingFinderPlugin.implingFallbackGetEndpoint, ImplingFinderPlugin.FALLBACK_SUPABASE_ANON_KEY);
                for (ImplingFinderData data : fallbackResults) {
                    if (wantsAny || ids.contains(data.getNpcid())) {
                        implings.add(data);
                    }
                }
            } catch (Exception fallbackException) {
                logger.error("Fallback Supabase read also failed", fallbackException);
            }
        }

        Collections.sort(implings, Collections.reverseOrder());
        if (implings.size() > 25)
            implings = implings.subList(0, 25);
        return implings;
    }

    /**
     * Fetches the current contents of an implings_recent view - a
     * restricted, read-only view that only ever exposes sightings from the
     * last 10 minutes. Used for both the primary and fallback Supabase
     * projects, since they're both PostgREST and both expose the same
     * bare-JSON-array shape - the only difference is which URL/key gets
     * passed in. Neither anon key has read access to its own raw implings
     * table, only this view.
     */
    private List<ImplingFinderData> fetchRecent(String endpoint, String apiKey) throws Exception {
        Request request = new Request.Builder()
                .url(endpoint + "?select=*")
                .addHeader("apikey", apiKey)
                .addHeader("Authorization", "Bearer " + apiKey)
                .build();

        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                logger.error("Recent-implings request unsuccessful: " + response.code());
                return Collections.emptyList();
            }
            String body = response.body().string();
            Type listType = new TypeToken<List<ImplingFinderData>>() {}.getType();
            List<ImplingFinderData> result = getGson().fromJson(body, listType);
            return result != null ? result : Collections.emptyList();
        }
    }


    private Gson getGson() {
        return gsonBuilder.registerTypeAdapter(Instant.class, new InstantSecondsConverter()).create();
    }

    /**
     * Serializes/Deserializes {@link Instant} using {@link Instant#getEpochSecond()}/{@link Instant#ofEpochSecond(long)}
     */
    private static class InstantSecondsConverter implements JsonSerializer<Instant>, JsonDeserializer<Instant>
    {
        @Override
        public JsonElement serialize(Instant src, Type srcType, JsonSerializationContext context) {
            return new JsonPrimitive(src.getEpochSecond());
        }

        @Override
        public Instant deserialize(JsonElement json, Type type, JsonDeserializationContext context)
                throws JsonParseException {
            return Instant.ofEpochSecond(json.getAsLong());
        }
    }
}

package com.hablapatabla.implingfinder;
import net.runelite.client.config.Config;
