    private List<ImplingFinderData> implingsToUpload = new ArrayList<>();

    @Setter(AccessLevel.PACKAGE)
    private List<ImplingFinderData> remotelyFetchedImplings = new ArrayList<>();

    public static final int RECENT_IMPLINGS_ID = -1;

